 const name=prompt.split(/[.!?,]/)[0].replace(/^(a|an|the)\s+/i,'').trim().slice(0,45)||'New add-on';
 const id=slug(name);
 const entity=/(pet|companion|mob|golem|creature|villager|dragon|wolf|zombie|animal|monster|firefly)/i.test(prompt);
 const tameable=/(pet|companion|tame|tameable)/i.test(prompt);
 const item=/(item|sword|tool|food|flower|crop|seed|apple|potion)/i.test(prompt);
 const files=[];
 const manifest=(packName,typeId)=>({format_version:2,header:{name:packName,description:`Created with Blocksmith · ${name}`,uuid:uuid(),version:[1,0,0],min_engine_version:[1,20,0]},modules:[{type:typeId,uuid:uuid(),version:[1,0,0]}]});
 if(type!=='resource'){
  const bpManifest=manifest(`${name} BP`,'data');
  files.push({path:'behavior_pack/manifest.json',content:JSON.stringify(bpManifest,null,2)});
  if(entity){
   const entityName=`${id}:${id}`;
   const components={'minecraft:type_family':{family:[id,'mob']},'minecraft:health':{value:20,max:20},'minecraft:movement':{value:0.25},'minecraft:collision_box':{width:0.6,height:1.8},'minecraft:physics':{},'minecraft:pushable':{is_pushable:true,is_pushable_by_piston:true},'minecraft:nameable':{},'minecraft:behavior.float':{priority:0},'minecraft:behavior.random_stroll':{priority:7,speed_multiplier:0.8},'minecraft:behavior.look_at_player':{priority:8,look_distance:6,probability:0.02},'minecraft:behavior.random_look_around':{priority:9},'minecraft:underwater_movement':{value:0.02},'minecraft:scale':{value:0.8}};
   const events={'minecraft:entity_spawned':{add:{component_groups:['bs:calm']}}};
   const componentGroups={'bs:calm':{'minecraft:damage_sensor':{triggers:{cause:'fall',deals_damage:false}}}};
   if(tameable){
    components['minecraft:tameable']={probability:1.0,tame_items:['minecraft:bone'],tame_event:{event:'bs:on_tame',target:'self'}};
    events['bs:on_tame']={add:{component_groups:['bs:tamed']}};
    componentGroups['bs:tamed']={'minecraft:is_tamed':{},'minecraft:behavior.follow_owner':{priority:2,speed_multiplier:1.1,start_distance:10,stop_distance:2}};
   }
   const mob={format_version:'1.20.50','minecraft:entity':{description:{identifier:entityName,is_spawnable:true,is_summonable:true,is_experimental:false,properties:{'minecraft:has_nametag':{type:'bool',default:true,client_sync:true}}},components,events,component_groups:componentGroups}};
