`});return {name,description:prompt,files,icon:entity?'🧌':item?'🌱':'🧱',id}}
async function askServer(prompt,context){if(!state.url)throw Error('Set your server URL in connection settings.');const content=`Create Minecraft Bedrock Edition add-on starter files for this idea: ${prompt}

${context?`Research context (use only as a guide): ${context}
`:''}Return ONLY a JSON object of the shape {"name":"short title","files":[{"path":"behavior_pack/manifest.json","content":"..."}]} with complete valid JSON file contents as strings. Include a valid format_version 2 pack manifest with unique UUIDs. Include an entity definition when appropriate. Keep paths relative and safe. Do not return markdown.`;const r=await fetch(state.url+'/chat/completions',{method:'POST',headers:{'Content-Type':'application/json',...(state.key?{Authorization:'Bearer '+state.key}:{})},body:JSON.stringify({model:state.model||'local-model',messages:[{role:'system',content:'You are Blocksmith, a careful Minecraft Bedrock add-on engineer. Return valid starter pack files only. Be accurate and concise.'},{role:'user',content}],temperature:.3}),signal:AbortSignal.timeout(120000)});if(!r.ok)throw Error(`Model server returned HTTP ${r.status}`);const d=await r.json();let text=d.choices?.[0]?.message?.content||'';text=text.replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'');const obj=JSON.parse(text);if(!Array.isArray(obj.files)||!obj.files.length)throw Error('Model response did not contain pack files.');return {name:obj.name||'AI generated add-on',description:prompt,icon:'✦',files:obj.files.map(f=>({path:f.path.replace(/^/+|\.\.(/|$)/g,''),content:typeof f.content==='string'?f.content:JSON.stringify(f.content,null,2)})).filter(f=>f.path&&f.path.endsWith('.json')||f.path.endsWith('.txt')||f.path.endsWith('.lang')),id:slug(obj.name||prompt)}}
